/**
 * The `library_sections` seed (0086): one insert-only row per code design, in
 * `DESIGNS` order. `ON CONFLICT (key) DO NOTHING`, so a re-run never overwrites
 * what an admin edited. Generated by `pnpm --filter @workspace/store-sections
 * section:sql`; a test checks the committed migration contains this output.
 */
import { designSlotTree } from "../designs/photo-slots";
import type { Design } from "../designs/builder";

const sqlText = (value: string) => `'${value.replace(/'/g, "''")}'`;

/** JSON with object keys sorted, so the generated SQL never depends on authoring order. */
function stableJson(value: unknown): string {
  return JSON.stringify(value, (_key, v: unknown) =>
    v && typeof v === "object" && !Array.isArray(v)
      ? Object.fromEntries(Object.entries(v).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)))
      : v,
  );
}

const sqlJson = (value: unknown) => `${sqlText(stableJson(value))}::jsonb`;

const sqlTextArray = (values: readonly string[]) => (values.length === 0 ? "'{}'::text[]" : `ARRAY[${values.map(sqlText).join(", ")}]::text[]`);

export function librarySectionSeedSql(design: Design, index: number): string {
  return `INSERT INTO library_sections (key, category, subcategory, name, description, keywords, tree, sort_order)
VALUES (
  ${sqlText(design.id)},
  ${sqlText(design.category)},
  ${sqlText(design.subcategory)},
  ${sqlJson(design.name)},
  ${sqlJson(design.description)},
  ${sqlTextArray(design.keywords)},
  ${sqlJson(designSlotTree(design))},
  ${index * 10}
)
ON CONFLICT (key) DO NOTHING;
`;
}

export function librarySectionsSeedSql(designs: readonly Design[]): string {
  return designs.map((design, index) => librarySectionSeedSql(design, index)).join("\n");
}
